+
+    // Security state
+    private SecuritySettings? securitySettings;
+    private bool showPasswordPanel;
+    private string currentPassword = "";
+    private string newPassword = "";
+    private string confirmPassword = "";
+    private string? passwordError;
+    private bool showConfirmDialog;
+    private string? sessionToRevoke;
+
+    // Appearance state
+    private EditableAppearance editAppearance = new();
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadAllSettings();
+        isLoading = false;
+    }
+
+    private async Task LoadAllSettings()
+    {
+        var profile = await SettingsService.GetProfileAsync();
+        savedProfile = profile;
+        editProfile = EditableProfile.FromRecord(profile);
+
+        var notifs = await SettingsService.GetNotificationPrefsAsync();
+        editNotifications = EditableNotificationPrefs.FromRecord(notifs);
+
+        securitySettings = await SettingsService.GetSecuritySettingsAsync();
+
+        var appearance = await SettingsService.GetAppearanceAsync();
+        editAppearance = EditableAppearance.FromRecord(appearance);
+    }
+
+    private void SetSection(string section)
+    {
+        activeSection = section;
+    }
+
+    // Profile methods
+    private async Task SaveProfile()
+    {
+        var profile = editProfile.ToRecord();
+        await SettingsService.SaveProfileAsync(profile);
+        savedProfile = profile;
+        ShowToast("Profile saved successfully!", "success");
+    }
+
+    private void DiscardProfileChanges()
+    {
+        if (savedProfile != null)
+        {
+            editProfile = EditableProfile.FromRecord(savedProfile);
+        }
+    }
+
+    // Notifications methods
+    private void ToggleMutedChannel(string channel, bool muted)
+    {
+        if (muted && !editNotifications.MutedChannels.Contains(channel))
+        {
+            editNotifications.MutedChannels.Add(channel);
+        }
+        else if (!muted)
+        {
+            editNotifications.MutedChannels.Remove(channel);
+        }
+    }
+
+    private async Task SaveNotifications()
+    {
+        var prefs = editNotifications.ToRecord();
+        await SettingsService.SaveNotificationPrefsAsync(prefs);
+        ShowToast("Notification preferences saved!", "success");
+    }
+
+    // Security methods
+    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;
+
+    private async Task UpdatePassword()
+    {
+        passwordError = null;
+        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
+        {
+            passwordError = "All password fields are required.";
+            return;
+        }
+        if (newPassword != confirmPassword)
+        {
+            passwordError = "New password and confirmation do not match.";
+            return;
+        }
+        try
+        {
+            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
+            currentPassword = "";
+            newPassword = "";
+            confirmPassword = "";
+            showPasswordPanel = false;
+            securitySettings = await SettingsService.GetSecuritySettingsAsync();
+            ShowToast("Password updated successfully!", "success");
+        }
+        catch (Exception ex)
+        {
+            passwordError = ex.Message;
+        }
+    }
+
+    private void RequestRevoke(string sessionId)
+    {
+        sessionToRevoke = sessionId;
+        showConfirmDialog = true;
+    }
+
+    private void CancelRevoke()
+    {
+        sessionToRevoke = null;
+        showConfirmDialog = false;
+    }
+
+    private async Task ConfirmRevoke()
+    {
+        if (sessionToRevoke != null)
+        {
+            await SettingsService.RevokeSessionAsync(sessionToRevoke);
+            securitySettings = await SettingsService.GetSecuritySettingsAsync();
+            ShowToast("Session revoked.", "success");
+        }
+        showConfirmDialog = false;
+        sessionToRevoke = null;
+    }
+
+    // Appearance methods
+    private string GetPreviewClasses()
+    {
+        var classes = $"preview-theme-{editAppearance.Theme.ToLowerInvariant()}";
+        classes += $" preview-font-{editAppearance.FontSize.ToLowerInvariant()}";
+        if (editAppearance.CompactMode) classes += " preview-compact";
+        return classes;
+    }
+
+    private async Task SaveAppearance()
+    {
+        var settings = editAppearance.ToRecord();
+        await SettingsService.SaveAppearanceAsync(settings);
+        ShowToast("Appearance settings saved!", "success");
+    }
+
+    // Toast
+    private void ShowToast(string message, string type)
+    {
+        toastMessage = message;
+        toastType = type;
+        toastTimer?.Dispose();
+        toastTimer = new System.Timers.Timer(3000);
+        toastTimer.Elapsed += (_, _) =>
+        {
+            toastMessage = null;
+            InvokeAsync(StateHasChanged);
+            toastTimer?.Dispose();
+        };
+        toastTimer.AutoReset = false;
+        toastTimer.Start();
+    }
+
+    public void Dispose()
+    {
+        toastTimer?.Dispose();
+    }
+
+    // Editable models
+    private class EditableProfile
+    {
+        public string DisplayName { get; set; } = "";
+        public string Email { get; set; } = "";
+        public string AvatarUrl { get; set; } = "";
+        public string Bio { get; set; } = "";
+
+        public static EditableProfile FromRecord(UserProfile p) => new()
+        {
+            DisplayName = p.DisplayName,
+            Email = p.Email,
+            AvatarUrl = p.AvatarUrl,
+            Bio = p.Bio
+        };
+
+        public UserProfile ToRecord() => new(DisplayName, Email, AvatarUrl, Bio);
+    }
+
+    private class EditableNotificationPrefs
+    {
+        public bool EmailNotifications { get; set; }
+        public bool PushNotifications { get; set; }
+        public bool WeeklyDigest { get; set; }
+        public List<string> MutedChannels { get; set; } = new();
+
+        public static EditableNotificationPrefs FromRecord(NotificationPrefs p) => new()
+        {
+            EmailNotifications = p.EmailNotifications,
+            PushNotifications = p.PushNotifications,
+            WeeklyDigest = p.WeeklyDigest,
+            MutedChannels = new List<string>(p.MutedChannels)
+        };
+
+        public NotificationPrefs ToRecord() => new(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
+    }
+
+    private class EditableAppearance
+    {
+        public string Theme { get; set; } = "Light";
+        public string FontSize { get; set; } = "Medium";
+        public string Language { get; set; } = "en";
+        public bool CompactMode { get; set; }
+
+        public static EditableAppearance FromRecord(AppearanceSettings s) => new()
+        {
+            Theme = s.Theme,
+            FontSize = s.FontSize,
+            Language = s.Language,
+            CompactMode = s.CompactMode
+        };
+
+        public AppearanceSettings ToRecord() => new(Theme, FontSize, Language, CompactMode);
+    }
+}
